1	import 'dart:async';
2	
3	import 'package:flutter/material.dart';
4	import 'package:flutter/semantics.dart';
5	import 'package:flutter_bloc/flutter_bloc.dart';
6	
7	import '../../../../core/design_tokens.dart';
8	import '../../../../core/widgets/app_button.dart';
9	import '../cubit/audio_entry_cubit.dart';
10	import '../cubit/text_entry_cubit.dart';
11	
12	/// The Insertion Modal — a 3-tab bottom sheet (Texto/Áudio/Foto) opened
13	/// from the Home/Chat "+" control (`placeholder_screens.dart`). Texto and
14	/// Áudio are both functional as of spec-3-2 (Boundaries) — Foto still
15	/// renders its own idle, non-interactive placeholder (Story 3.3).
16	class InsertionModal extends StatelessWidget {
17	  const InsertionModal({required this.cubit, required this.audioCubit, super.key});
18	
19	  final TextEntryCubit cubit;
20	  final AudioEntryCubit audioCubit;
21	
22	  /// Presents the modal exactly as the Boundaries dictate:
23	  /// `showModalBottomSheet(isScrollControlled: true, barrierColor:
24	  /// colorScrimHeavy)`, `radiusLg` top corners + `elevation2` (drawn by
25	  /// this widget's own `Container`, not Material's `elevation` double —
26	  /// same convention `ConfirmationDialog`'s card already uses), and a
27	  /// `durationSheetUp` entrance that collapses to zero under Reduce
28	  /// Motion (`MediaQuery.disableAnimations`).
29	  ///
30	  /// [cubit]/[audioCubit] are both fresh, `get_it`-factory-scoped
31	  /// instances — one pair per "+" tap (Boundaries: "Modal open resets") —
32	  /// closed here once the sheet is gone, regardless of how it closed
33	  /// (Salvar success, "x", swipe-down, or barrier dismiss) — the caller
34	  /// never has to remember to do this itself.
35	  static Future<void> show(
36	    BuildContext context, {
37	    required TextEntryCubit cubit,
38	    required AudioEntryCubit audioCubit,
39	  }) async {
40	    final reduceMotion = MediaQuery.of(context).disableAnimations;
41	    final controller =
42	        BottomSheet.createAnimationController(Navigator.of(context))
43	          ..duration = reduceMotion
44	              ? Duration.zero
45	              : DesignTokens.durationSheetUp
46	          // Boundaries only names the entrance, but Reduce Motion should
47	          // collapse the exit the same way — otherwise dismissing the
48	          // sheet would still animate for anyone who asked for no motion.
49	          ..reverseDuration = reduceMotion ? Duration.zero : null;
50	    try {
51	      await showModalBottomSheet<void>(
52	        context: context,
53	        isScrollControlled: true,
54	        barrierColor: DesignTokens.colorScrimHeavy,
55	        backgroundColor: Colors.transparent,
56	        elevation: 0,
57	        transitionAnimationController: controller,
58	        builder: (_) => InsertionModal(cubit: cubit, audioCubit: audioCubit),
59	      );
60	    } finally {
61	      // `showModalBottomSheet`'s own Future completes as soon as the
62	      // route is popped — *before* the exit (`reverse()`) animation the
63	      // framework drives on this same controller actually finishes.
64	      // Disposing immediately would cancel that animation's ticker
65	      // mid-flight, permanently freezing the sheet on screen (its
66	      // `AnimatedBuilder` keeps rendering the controller's last value,
67	      // and the route itself never reaches `AnimationStatus.dismissed`
68	      // to be removed from the `Overlay`). Documented behavior
69	      // (`BottomSheet.transitionAnimationController`'s own doc: "the
70	      // caller is responsible for disposing it when the controller is
71	      // no longer needed") — waiting for `dismissed` first is that
72	      // "no longer needed" point.
73	      if (!controller.isDismissed) {
74	        final animationDone = Completer<void>();
75	        void onStatusChange(AnimationStatus status) {
76	          if (status == AnimationStatus.dismissed) {
77	            animationDone.complete();
78	          }
79	        }
80	
81	        controller.addStatusListener(onStatusChange);
82	        await animationDone.future;
83	        controller.removeStatusListener(onStatusChange);
84	      }
85	      controller.dispose();
86	      await cubit.close();
87	      // Review finding: dismissing the whole modal while recording/
88	      // processing (the "x" button, swipe-down, or barrier tap — as
89	      // opposed to switching to another tab, which already went through
90	      // this same `cancel()`) never stopped the native recording session;
91	      // `close()` alone only cancels the elapsed-seconds timer, not the
92	      // recorder itself. `discardPreserved: true` — unlike a tab switch,
93	      // there's no "switch back later" to preserve a transcribed/failed
94	      // recording for, so its temp file must be cleaned up here too
95	      // (Review finding) rather than leaking on disk forever once
96	      // `close()` below makes the cubit unreachable.
97	      await audioCubit.cancel(discardPreserved: true);
98	      await audioCubit.close();
99	    }
100	  }
101	
102	  @override
103	  Widget build(BuildContext context) {
104	    return MultiBlocProvider(
105	      providers: [
106	        BlocProvider.value(value: cubit),
107	        BlocProvider.value(value: audioCubit),
108	      ],
109	      child: const _InsertionModalBody(),
110	    );
111	  }
112	}
113	
114	/// Coarse `AudioCaptureState` discriminator used only to decide whether a
115	/// given emission is a genuine transition worth announcing — e.g.
116	/// [AudioRecording]'s own per-second timer tick re-emits the same kind
117	/// repeatedly and must never re-announce "Gravando áudio" every second.
118	enum _AudioAnnounceKind { idle, recording, processing, transcribed, saving, saved, error }
119	
120	_AudioAnnounceKind _audioAnnounceKindOf(AudioCaptureState state) => switch (state) {
121	  AudioIdle() => _AudioAnnounceKind.idle,
122	  AudioRecording() => _AudioAnnounceKind.recording,
123	  AudioProcessing() => _AudioAnnounceKind.processing,
124	  AudioTranscribed(saving: true) => _AudioAnnounceKind.saving,
125	  AudioTranscribed() => _AudioAnnounceKind.transcribed,
126	  AudioSaved() => _AudioAnnounceKind.saved,
127	  AudioError() => _AudioAnnounceKind.error,
128	};
129	
130	class _InsertionModalBody extends StatefulWidget {
131	  const _InsertionModalBody();
132	
133	  @override
134	  State<_InsertionModalBody> createState() => _InsertionModalBodyState();
135	}
136	
137	class _InsertionModalBodyState extends State<_InsertionModalBody> {
138	  final _textController = TextEditingController();
139	
140	  /// The Áudio tab's own text field controller — lifted up here rather
141	  /// than owned by `_AudioTab` itself so it survives `_AudioTab` being
142	  /// rebuilt on every `AudioCaptureState` change without losing cursor
143	  /// position/focus, same rationale as [_textController] living here
144	  /// instead of inside `_TextoTab`.
145	  final _audioTextController = TextEditingController();
146	
147	  /// The last `AudioTranscribed.path` this controller's text was synced
148	  /// from — only a *new* transcription (a different/first path) resets
149	  /// the controller's text; the user's own edits via `onChanged` never
150	  /// get clobbered by an unrelated rebuild.
151	  String? _lastSyncedAudioPath;
152	
153	  /// Tracks the previously-seen `activeTab` so the listener can tell a
154	  /// genuine tab switch apart from the many other `TextEntryIdle`
155	  /// emissions a keystroke produces (`updateText` also emits `Idle`) —
156	  /// initialized from the cubit's own current state so the very first
157	  /// comparison (before any emission the listener sees) is still correct.
158	  late CaptureTab _lastAnnouncedTab;
159	
160	  /// Same "only announce a genuine transition" guard as [_lastAnnouncedTab],
161	  /// for `AudioEntryCubit` (see [_audioAnnounceKindOf]).
162	  late _AudioAnnounceKind _lastAudioAnnouncedKind;
163	
164	  @override
165	  void initState() {
166	    super.initState();
167	    _lastAnnouncedTab = context.read<TextEntryCubit>().state.activeTab;
168	    _lastAudioAnnouncedKind = _audioAnnounceKindOf(
169	      context.read<AudioEntryCubit>().state,
170	    );
171	  }
172	
173	  @override
174	  void dispose() {
175	    _textController.dispose();
176	    _audioTextController.dispose();
177	    super.dispose();
178	  }
179	
180	  // Labels for the 3 tabs, shared between the announcement below and
181	  // `_TabBar`'s own rendering (`_TabBar._tabs`) — kept here too since
182	  // `selectTab`'s announcement needs the label for whichever tab the
183	  // user just switched *to*, not the cubit's own (enum-only) state.
184	  static const _tabLabels = {
185	    CaptureTab.texto: 'Texto',
186	    CaptureTab.audio: 'Áudio',
187	    CaptureTab.foto: 'Foto',
188	  };
189	
190	  // Mirrors `account_settings_screen.dart`'s own `_announce` — VoiceOver
191	  // (this app is iOS-only) doesn't reliably treat a live-region subtree
192	  // update as an announcement on its own, so every state change this
193	  // story introduces — saving, success, failure, and a tab switch — is
194	  // spoken explicitly here instead (Acceptance Criteria: "no
195	  // color/animation alone").
196	  Future<void> _announce(String message) async {
197	    if (!mounted) {
198	      return;
199	    }
200	    await SemanticsService.sendAnnouncement(
201	      View.of(context),
202	      message,
203	      TextDirection.ltr,
204	    );
205	  }
206	
207	  void _onTextEntryStateChange(BuildContext context, TextEntryState state) {
208	    // Review finding: a tab switch (re-emitted as `TextEntryIdle`,
209	    // same as every keystroke) previously went unannounced —
210	    // detected here by comparing against the last tab seen, so a
211	    // plain keystroke (same `activeTab`) never re-triggers it.
212	    if (state.activeTab != _lastAnnouncedTab) {
213	      final previousTab = _lastAnnouncedTab;
214	      _lastAnnouncedTab = state.activeTab;
215	      _announce('Aba ${_tabLabels[state.activeTab]} selecionada');
216	      // spec-3-2's Code Map: tab-switch detection also drives
217	      // `AudioEntryCubit.startRecording()`/`.cancel()` — entering Áudio
218	      // starts recording immediately (Acceptance Criteria), leaving it
219	      // stops/releases the recorder (I/O matrix: "Leave tab
220	      // mid-recording"), never the full Story 3.4 cancel choreography.
221	      final audioCubit = context.read<AudioEntryCubit>();
222	      if (state.activeTab == CaptureTab.audio) {
223	        unawaited(audioCubit.startRecording());
224	      } else if (previousTab == CaptureTab.audio) {
225	        unawaited(audioCubit.cancel());
226	      }
227	    }
228	    switch (state) {
229	      case TextEntrySaved():
230	        // I/O matrix: "success closes the modal". Review finding:
231	        // wait for the announcement to actually be sent before
232	        // popping — previously fired-and-forgot in the same tick,
233	        // risking the announcement being cut off by the dismiss
234	        // transition.
235	        unawaited(
236	          _announce('Registro salvo').then((_) {
237	            if (context.mounted) {
238	              Navigator.of(context).pop();
239	            }
240	          }),
241	        );
242	      case TextEntrySaving():
243	        _announce('Salvando registro');
244	      case TextEntryError():
245	        _announce(state.message);
246	      case TextEntryIdle():
247	        break;
248	    }
249	  }
250	
251	  void _onAudioStateChange(BuildContext context, AudioCaptureState state) {
252	    if (state is AudioTranscribed && state.path != _lastSyncedAudioPath) {
253	      _lastSyncedAudioPath = state.path;
254	      _audioTextController.text = state.text;
255	    }
256	    final kind = _audioAnnounceKindOf(state);
257	    if (kind == _lastAudioAnnouncedKind) {
258	      return;
259	    }
260	    _lastAudioAnnouncedKind = kind;
261	    switch (state) {
262	      case AudioRecording():
263	        _announce('Gravando áudio');
264	      case AudioProcessing():
265	        _announce('Transcrevendo áudio');
266	      case AudioTranscribed(saving: true):
267	        _announce('Salvando registro');
268	      case AudioTranscribed():
269	        _announce('Transcrição concluída. Revise o texto antes de salvar.');
270	      case AudioError(message: final message):
271	        _announce(message);
272	      case AudioSaved():
273	        // Same "wait for the announcement" rationale as
274	        // `TextEntrySaved` above.
275	        unawaited(
276	          _announce('Registro salvo').then((_) {
277	            if (context.mounted) {
278	              Navigator.of(context).pop();
279	            }
280	          }),
281	        );
282	      case AudioIdle():
283	        // Review finding: the one `AudioCaptureState` transition
284	        // previously never announced — reachable today only via
285	        // `cancel()` resetting from `AudioRecording` (a tab switch away
286	        // mid-recording), which happened to already be covered by the
287	        // separate tab-switch announcement above, masking the gap.
288	        _announce('Gravação cancelada');
289	    }
290	  }
291	
292	  @override
293	  Widget build(BuildContext context) {
294	    return BlocListener<AudioEntryCubit, AudioCaptureState>(
295	      listener: _onAudioStateChange,
296	      // Review finding: `isSaving` below previously only read
297	      // `TextEntryCubit`'s state, so the tab bar/"x" close button stayed
298	      // tappable while an *audio* save was in flight (`AudioTranscribed.
299	      // saving == true`) — the same race Story 3.1's own review fixed for
300	      // the Texto tab, just unguarded on the Áudio side. Wrapping in this
301	      // `BlocBuilder` makes the whole subtree rebuild on an `AudioEntryCubit`
302	      // state change too, not only a `TextEntryCubit` one.
303	      child: BlocBuilder<AudioEntryCubit, AudioCaptureState>(
304	        builder: (context, audioState) {
305	          final isAudioSaving =
306	              audioState is AudioTranscribed && audioState.saving;
307	          return BlocConsumer<TextEntryCubit, TextEntryState>(
308	            listener: _onTextEntryStateChange,
309	            builder: (context, state) {
310	              final isSaving = state is TextEntrySaving || isAudioSaving;
311	              return Container(
312	                padding: DesignTokens.screenPadding,
313	                decoration: const BoxDecoration(
314	                  color: DesignTokens.colorSurfaceElevated,
315	                  borderRadius: BorderRadius.vertical(
316	                    top: Radius.circular(DesignTokens.radiusLg),
317	                  ),
318	                  boxShadow: DesignTokens.elevation2,
319	                ),
320	                child: Padding(
321	                  // Keeps the Texto field clear of the on-screen keyboard —
322	                  // the sheet is `isScrollControlled: true`, so it already
323	                  // grows to fit; this is the standard companion fix for
324	                  // the keyboard inset itself.
325	                  padding: EdgeInsets.only(
326	                    bottom: MediaQuery.of(context).viewInsets.bottom,
327	                  ),
328	                  child: SafeArea(
329	                    top: false,
330	                    child: Column(
331	                      mainAxisSize: MainAxisSize.min,
332	                      crossAxisAlignment: CrossAxisAlignment.stretch,
333	                      children: [
334	                        Row(
335	                          crossAxisAlignment: CrossAxisAlignment.center,
336	                          children: [
337	                            Expanded(
338	                              child: _TabBar(
339	                                activeTab: state.activeTab,
340	                                isSaving: isSaving,
341	                              ),
342	                            ),
343	                            const SizedBox(width: DesignTokens.spacingSm),
344	                            _CloseButton(isSaving: isSaving),
345	                          ],
346	                        ),
347	                        const SizedBox(height: DesignTokens.spacingMd),
348	                        switch (state.activeTab) {
349	                          CaptureTab.texto => _TextoTab(
350	                            controller: _textController,
351	                            state: state,
352	                          ),
353	                          CaptureTab.audio => _AudioTab(
354	                            controller: _audioTextController,
355	                          ),
356	                          CaptureTab.foto => const _IdleTabPlaceholder(
357	                            icon: Icons.photo_camera_outlined,
358	                            label: 'Foto chega em breve',
359	                          ),
360	                        },
361	                      ],
362	                    ),
363	                  ),
364	                ),
365	              );
366	            },
367	          );
368	        },
369	      ),
370	    );
371	  }
372	}
