374	class _TabBar extends StatelessWidget {
375	  const _TabBar({required this.activeTab, required this.isSaving});
376	
377	  final CaptureTab activeTab;
378	
379	  /// Review finding: a save already in flight must disable the tab bar —
380	  /// without this, switching tabs mid-save let that stale `save()` call's
381	  /// eventual `TextEntrySaved`/`TextEntryError` land against a tab/text
382	  /// the user has since left (popping the modal unexpectedly, or showing
383	  /// an error nobody is looking at). `TextEntryCubit.selectTab` also
384	  /// guards against this independently — this is the UI-level half of
385	  /// that same fix.
386	  final bool isSaving;
387	
388	  static const _tabs = [
389	    (CaptureTab.texto, 'Texto'),
390	    (CaptureTab.audio, 'Áudio'),
391	    (CaptureTab.foto, 'Foto'),
392	  ];
393	
394	  @override
395	  Widget build(BuildContext context) {
396	    return Row(
397	      children: [
398	        for (var i = 0; i < _tabs.length; i++) ...[
399	          Expanded(
400	            child: _TabButton(
401	              tab: _tabs[i].$1,
402	              label: _tabs[i].$2,
403	              isActive: _tabs[i].$1 == activeTab,
404	              isSaving: isSaving,
405	            ),
406	          ),
407	          if (i < _tabs.length - 1)
408	            const SizedBox(width: DesignTokens.spacingSm),
409	        ],
410	      ],
411	    );
412	  }
413	}
414	
415	class _TabButton extends StatelessWidget {
416	  const _TabButton({
417	    required this.tab,
418	    required this.label,
419	    required this.isActive,
420	    required this.isSaving,
421	  });
422	
423	  final CaptureTab tab;
424	  final String label;
425	  final bool isActive;
426	  final bool isSaving;
427	
428	  @override
429	  Widget build(BuildContext context) {
430	    return Semantics(
431	      button: true,
432	      selected: isActive,
433	      label: 'Aba $label',
434	      // Review finding: without this, VoiceOver can also pick up the
435	      // inner `Text(label)`'s own implicit semantics as a separate node,
436	      // announcing the tab name twice back-to-back.
437	      excludeSemantics: true,
438	      child: Material(
439	        color: isActive ? DesignTokens.colorPrimary : Colors.transparent,
440	        borderRadius: const BorderRadius.all(
441	          Radius.circular(DesignTokens.radiusSm),
442	        ),
443	        child: InkWell(
444	          borderRadius: const BorderRadius.all(
445	            Radius.circular(DesignTokens.radiusSm),
446	          ),
447	          // Review finding: `null` while a save is in flight, same
448	          // "disabled `onTap` can never start a second, overlapping call"
449	          // convention `account_settings_screen.dart`'s `Switch` already
450	          // uses.
451	          onTap: isSaving
452	              ? null
453	              : () => context.read<TextEntryCubit>().selectTab(tab),
454	          child: Container(
455	            constraints: const BoxConstraints(
456	              minHeight: DesignTokens.insertionModalTapTargetMin,
457	            ),
458	            alignment: Alignment.center,
459	            padding: DesignTokens.buttonPadding,
460	            child: Text(
461	              label,
462	              style: DesignTokens.textLabelMd.copyWith(
463	                color: isActive
464	                    ? DesignTokens.colorOnPrimary
465	                    : DesignTokens.colorTextPrimary,
466	              ),
467	            ),
468	          ),
469	        ),
470	      ),
471	    );
472	  }
473	}
474	
475	class _CloseButton extends StatelessWidget {
476	  const _CloseButton({required this.isSaving});
477	
478	  /// Review finding — same rationale as `_TabBar.isSaving`: disabled
479	  /// while a save is in flight, so "x" can't pop the modal out from under
480	  /// a `save()` call that's about to emit `TextEntrySaved`/`TextEntryError`
481	  /// against the tab/text it captured at call time. (Swipe-down/barrier
482	  /// dismiss can still close the sheet mid-save — that gap is tracked
483	  /// separately in `deferred-work.md`, not part of this fix.)
484	  final bool isSaving;
485	
486	  @override
487	  Widget build(BuildContext context) {
488	    return Semantics(
489	      button: true,
490	      label: 'Fechar',
491	      child: InkWell(
492	        borderRadius: const BorderRadius.all(
493	          Radius.circular(DesignTokens.radiusFull),
494	        ),
495	        // I/O matrix: "Cancel before save" — closes/resets, never calls
496	        // `create` (this handler never touches the cubit at all).
497	        onTap: isSaving ? null : () => Navigator.of(context).pop(),
498	        child: SizedBox(
499	          width: DesignTokens.insertionModalTapTargetMin,
500	          height: DesignTokens.insertionModalTapTargetMin,
501	          child: Icon(
502	            Icons.close,
503	            color: isSaving
504	                ? DesignTokens.colorTextSecondary
505	                : DesignTokens.colorTextPrimary,
506	          ),
507	        ),
508	      ),
509	    );
510	  }
511	}
