545	class _TextoTab extends StatelessWidget {
546	  const _TextoTab({required this.controller, required this.state});
547	
548	  final TextEditingController controller;
549	  final TextEntryState state;
550	
551	  @override
552	  Widget build(BuildContext context) {
553	    final isSaving = state is TextEntrySaving;
554	    // Review finding: also false while TextEntrySaved — the sheet is
555	    // about to pop (same rationale as TextEntryCubit.save()'s own guard),
556	    // so Salvar shouldn't be tappable during that brief window either.
557	    final canSave =
558	        controller.text.trim().isNotEmpty && !isSaving && state is! TextEntrySaved;
559	    return Column(
560	      mainAxisSize: MainAxisSize.min,
561	      crossAxisAlignment: CrossAxisAlignment.stretch,
562	      children: [
563	        TextField(
564	          controller: controller,
565	          enabled: !isSaving,
566	          minLines: 3,
567	          maxLines: null,
568	          // Mirrors `POST /entries`'s own `content` cap
569	          // (`openapi.yaml`: `maxLength: 20000`) — avoids an avoidable
570	          // round-trip failure for text typed past the backend's limit.
571	          maxLength: 20000,
572	          onChanged: (value) =>
573	              context.read<TextEntryCubit>().updateText(value),
574	          style: DesignTokens.textBodyLg.copyWith(
575	            color: DesignTokens.colorTextPrimary,
576	          ),
577	          decoration: InputDecoration(
578	            // prototype-extract.md §2.3's Texto state: placeholder
579	            // "Escreva livremente...".
580	            hintText: 'Escreva livremente...',
581	            // Review finding: suppresses Material's default "0/20000"
582	            // counter — the prototype's Texto state shows no such
583	            // element, and nothing here accounts for its styling.
584	            counterText: '',
585	            contentPadding: DesignTokens.textFieldContentPadding,
586	            border: const OutlineInputBorder(
587	              borderRadius: BorderRadius.all(
588	                Radius.circular(DesignTokens.radiusSm),
589	              ),
590	              borderSide: BorderSide(
591	                color: DesignTokens.colorBorder,
592	                width: DesignTokens.borderWidthDefault,
593	              ),
594	            ),
595	            focusedBorder: const OutlineInputBorder(
596	              borderRadius: BorderRadius.all(
597	                Radius.circular(DesignTokens.radiusSm),
598	              ),
599	              borderSide: BorderSide(
600	                color: DesignTokens.colorPrimary,
601	                width: DesignTokens.borderWidthEmphasis,
602	              ),
603	            ),
604	          ),
605	        ),
606	        if (state is TextEntryError) ...[
607	          const SizedBox(height: DesignTokens.spacingSm),
608	          Text(
609	            (state as TextEntryError).message,
610	            style: DesignTokens.textBodyMd.copyWith(
