927	/// A live (or frozen) amplitude-bar waveform. `amplitudeStream == null`
928	/// renders a static placeholder pattern at [opacity] instead of
929	/// subscribing — the "frozen" rendering `_AudioProcessingView` uses.
930	class _Waveform extends StatefulWidget {
931	  const _Waveform({required this.amplitudeStream, required this.opacity});
932	
933	  final Stream<double>? amplitudeStream;
934	  final double opacity;
935	
936	  @override
937	  State<_Waveform> createState() => _WaveformState();
938	}
939	
940	class _WaveformState extends State<_Waveform> {
941	  // `growable: true` — `build()` below reads this with `removeAt`/`add`
942	  // on every new amplitude sample, which `List.filled`'s own default
943	  // fixed-length list doesn't support.
944	  final List<double> _samples = List.filled(
945	    _waveformBarCount,
946	    0.1,
947	    growable: true,
948	  );
949	  StreamSubscription<double>? _subscription;
950	
951	  @override
952	  void initState() {
953	    super.initState();
954	    _subscription = widget.amplitudeStream?.listen(
955	      (amplitude) {
956	        if (!mounted) {
957	          return;
958	        }
959	        setState(() {
960	          _samples.removeAt(0);
961	          // `num.clamp` returns `num`, not `double` — `_samples` is
962	          // `List<double>`.
963	          _samples.add(amplitude.clamp(0.1, 1.0).toDouble());
964	        });
965	      },
966	      // Review finding: an unhandled `onError` turns a native amplitude-
967	      // stream error into an uncaught async exception — the waveform
968	      // just stays frozen on its last sample instead, no worse than the
969	      // already-handled "no live stream" (frozen/processing) case.
970	      onError: (_) {},
971	    );
972	  }
973	
974	  @override
975	  void dispose() {
976	    _subscription?.cancel();
977	    super.dispose();
978	  }
979	
980	  @override
981	  Widget build(BuildContext context) {
982	    return Opacity(
983	      opacity: widget.opacity,
984	      child: SizedBox(
985	        height: DesignTokens.spacing2xl,
986	        child: Row(
987	          mainAxisAlignment: MainAxisAlignment.center,
988	          crossAxisAlignment: CrossAxisAlignment.center,
989	          children: [
990	            for (var i = 0; i < _samples.length; i++) ...[
991	              AnimatedContainer(
992	                duration: DesignTokens.durationSheetUp,
993	                width: DesignTokens.spacingXs,
994	                height: DesignTokens.spacing2xl * _samples[i],
995	                decoration: const BoxDecoration(
996	                  color: DesignTokens.colorError,
997	                  borderRadius: BorderRadius.all(
998	                    Radius.circular(DesignTokens.radiusFull),
999	                  ),
1000	                ),
1001	              ),
1002	              if (i < _samples.length - 1)
1003	                const SizedBox(width: DesignTokens.spacingXs),
1004	            ],
1005	          ],
1006	        ),
1007	      ),
1008	    );
1009	  }
1010	}
