11	/// `AudioEntryCubit`'s own sealed state hierarchy — separate from
12	/// `TextEntryState` (Boundaries: "own sealed `AudioCaptureState`,
13	/// separate from `TextEntryState`"). Unlike `TextEntryState`, no common
14	/// base-class field: the 5 variants don't share a uniform shape the way
15	/// every `TextEntryState` always carries `activeTab`/`text` — [AudioIdle]
16	/// genuinely has nothing in common with [AudioTranscribed], for instance.
17	sealed class AudioCaptureState {
18	  const AudioCaptureState();
19	}
20	
21	/// The state immediately after the modal opens on the Áudio tab exits
22	/// (Never: this story's trivial cross-tab case), and the state a fresh
23	/// `AudioEntryCubit` always starts in.
24	class AudioIdle extends AudioCaptureState {
25	  const AudioIdle();
26	}
27	
28	/// Recording in progress — [elapsedSeconds] backs the running monospace
29	/// timer (Acceptance Criteria) and ticks once per second via
30	/// `AudioEntryCubit`'s own internal `Timer.periodic`.
31	class AudioRecording extends AudioCaptureState {
32	  const AudioRecording({required this.elapsedSeconds});
33	
34	  final int elapsedSeconds;
35	}
36	
37	/// Recording stopped, `AudioTranscriber.transcribe()` in flight —
38	/// `InsertionModal`'s own `_AudioTab` freezes the waveform at 35% opacity
39	/// for the whole duration of this state (Acceptance Criteria).
40	class AudioProcessing extends AudioCaptureState {
41	  const AudioProcessing({required this.path, required this.durationSeconds});
42	
43	  final String path;
44	  final int durationSeconds;
45	}
46	
47	/// Transcription succeeded (even to an empty string) — [text] is editable
48	/// before Salvar (Acceptance Criteria), mirrored into this state by
49	/// `AudioEntryCubit.updateText` the same way `TextEntryCubit.updateText`
50	/// mirrors the Texto field. [saving] is this story's `TextEntrySaving`
51	/// equivalent folded into one state instead of a separate sibling class —
52	/// both [path]/[durationSeconds] (needed for the eventual `create()` call)
53	/// stay fixed across a save attempt, so there's nothing a sibling state
54	/// would add that a boolean field doesn't already cover just as clearly.
55	class AudioTranscribed extends AudioCaptureState {
56	  const AudioTranscribed({
57	    required this.path,
58	    required this.durationSeconds,
59	    required this.text,
60	    required this.saving,
61	  });
62	
63	  final String path;
64	  final int durationSeconds;
65	  final String text;
66	  final bool saving;
67	
68	  AudioTranscribed copyWith({String? text, bool? saving}) => AudioTranscribed(
69	    path: path,
70	    durationSeconds: durationSeconds,
71	    text: text ?? this.text,
72	    saving: saving ?? this.saving,
73	  );
74	}
75	
76	/// A save attempt from [AudioTranscribed] succeeded — `InsertionModal`'s
77	/// listener reacts to this exactly like `TextEntrySaved` (announce, then
78	/// pop). Terminal, same rationale as `TextEntrySaved`'s own doc.
79	class AudioSaved extends AudioCaptureState {
80	  const AudioSaved();
81	}
82	
83	/// The last attempt failed — covers all 3 failure rows of the I/O matrix:
84	/// - Mic permission denied -> [path]/[durationSeconds] both `null` ("No
85	///   file to preserve"); [AudioEntryCubit.retry] re-requests permission.
86	/// - Transcription failed -> [path]/[durationSeconds] carry the preserved
87	///   file; [AudioEntryCubit.retry] re-transcribes it, never re-records.
88	/// - Save failed (incl. offline) -> same preserved [path]/
89	///   [durationSeconds]/[text] semantics as `TextEntryError`; the modal's
90	///   `_AudioTab` keeps showing the editable text with Salvar re-enabled
91	///   rather than routing back through [AudioEntryCubit.retry].
92	class AudioError extends AudioCaptureState {
93	  const AudioError({
94	    required this.path,
95	    required this.durationSeconds,
96	    required this.message,
97	    this.text,
98	  });
99	
100	  final String? path;
101	  final int? durationSeconds;
102	  final String message;
103	
104	  /// Non-null only for a save failure — lets `_AudioTab` keep rendering
105	  /// the editable text field under the inline error, same as
106	  /// `TextEntryError`'s own `_TextoTab` rendering.
107	  final String? text;
108	}
109	
110	/// Drives the Áudio tab's recording -> processing -> transcribed/error
111	/// pipeline (Intent). A fresh, `get_it`-factory-scoped instance per "+"
112	/// tap, same convention as `TextEntryCubit` — [MicRecorder]/
113	/// [AudioTranscriber] themselves stay long-lived `get_it` singletons
114	/// (`capture_injection.dart`), shared across every modal open the way
115	/// `EntriesRepository` already is for `TextEntryCubit`.
116	class AudioEntryCubit extends Cubit<AudioCaptureState> {
117	  AudioEntryCubit(this._micRecorder, this._audioTranscriber, this._repository)
118	    : super(const AudioIdle());
119	
120	  final MicRecorder _micRecorder;
121	  final AudioTranscriber _audioTranscriber;
122	  final EntriesRepository _repository;
123	
124	  Timer? _elapsedTimer;
125	
126	  /// Bumped by [cancel] so an in-flight [startRecording]/[stopRecording]
127	  /// continuation can tell "the user already left the Áudio tab while I
128	  /// was awaiting" apart from "nothing has changed since I started" —
129	  /// the same role `isClosed` already plays for `close()`, but for a tab
130	  /// switch that doesn't close the cubit itself (Review finding: without
131	  /// this, `cancel()` running mid-await either left the recorder running
132	  /// unobserved, or let a stale `stop()`/transcription result resurrect a
133	  /// flow the user already left).
134	  int _generation = 0;
135	
136	  /// Guards [stopRecording] against a second concurrent call (e.g. a fast
137	  /// double-tap on the stop control before the UI rebuilds past
138	  /// [AudioRecording]) — without this, a second `_micRecorder.stop()` call
139	  /// racing the first could return `null` (nothing left to stop) and
140	  /// overwrite a perfectly good [AudioProcessing]/transcription result
141	  /// with a bogus [AudioError] (Review finding).
142	  bool _stopping = false;
143	
144	  /// Forwarded straight from [MicRecorder.amplitudeStream] — lets
145	  /// `_AudioTab`'s waveform animate without ever importing `package:record`
146	  /// itself (Boundaries).
147	  Stream<double> get amplitudeStream => _micRecorder.amplitudeStream;
148	
149	  /// Starts recording — called from `InsertionModal`'s tab-switch
150	  /// listener the instant the Áudio tab becomes active (Acceptance
151	  /// Criteria: "recording starts immediately"), and again by [retry] when
152	  /// the last attempt failed before any file ever existed (permission
153	  /// denied). Ignored while a recording is already in progress, and —
154	  /// Review finding — ignored once the pipeline has moved past recording
155	  /// ([AudioProcessing]/[AudioTranscribed]/an [AudioError] that still
156	  /// carries a file): without this, re-entering the Áudio tab after a
157	  /// completed transcription silently discarded the transcribed text and
158	  /// started a brand-new recording over it. Only [AudioIdle] (fresh) or
159	  /// an [AudioError] with no file (nothing to discard) actually start.
160	  Future<void> startRecording() async {
161	    final current = state;
162	    final canStart =
163	        current is AudioIdle ||
164	        (current is AudioError && current.path == null);
165	    if (!canStart) {
166	      return;
167	    }
168	    final generation = ++_generation;
169	    bool hasPermission;
170	    try {
171	      hasPermission = await _micRecorder.hasPermission();
172	    } catch (_) {
173	      // Review finding: a thrown `PlatformException` (native-side error)
174	      // must never escape uncaught — surfaces through the same
175	      // error/retry path as a plain permission denial.
176	      if (isClosed || generation != _generation) {
177	        return;
178	      }
179	      emit(
180	        const AudioError(
181	          path: null,
182	          durationSeconds: null,
183	          message: 'Não foi possível acessar o microfone.',
184	        ),
185	      );
186	      return;
187	    }
188	    if (isClosed || generation != _generation) {
189	      return;
190	    }
191	    if (!hasPermission) {
192	      emit(
193	        const AudioError(
194	          path: null,
195	          durationSeconds: null,
196	          message:
197	              'Permissão de microfone negada. Toque em "Tentar novamente" '
198	              'para permitir o acesso.',
199	        ),
200	      );
201	      return;
202	    }
203	    try {
204	      await _micRecorder.start();
205	    } catch (_) {
206	      // Review finding: same rationale as the `hasPermission()` catch
207	      // above — a native-side start failure must surface through the
208	      // normal error/retry path instead of escaping uncaught.
209	      if (isClosed || generation != _generation) {
210	        return;
211	      }
212	      emit(
213	        const AudioError(
214	          path: null,
215	          durationSeconds: null,
216	          message: 'Não foi possível iniciar a gravação.',
217	        ),
218	      );
219	      return;
220	    }
221	    if (isClosed || generation != _generation) {
222	      // Review finding: `cancel()` bumped `_generation` (the user already
223	      // left the Áudio tab) while `start()` was in flight — stop/discard
224	      // the session we just started instead of leaving a live, unobserved
225	      // recording running.
226	      unawaited(_safeCancelRecorder());
227	      return;
228	    }
229	    _startElapsedTimer();
230	    emit(const AudioRecording(elapsedSeconds: 0));
231	  }
232	
233	  void _startElapsedTimer() {
234	    _elapsedTimer?.cancel();
235	    var elapsed = 0;
236	    _elapsedTimer = Timer.periodic(const Duration(seconds: 1), (_) {
237	      elapsed++;
238	      if (state is AudioRecording) {
239	        emit(AudioRecording(elapsedSeconds: elapsed));
240	      }
241	    });
242	  }
243	
244	  /// Stops recording and immediately kicks off transcription — the I/O
245	  /// matrix's "Happy path"/"Transcription fails" rows. Ignored outside
246	  /// [AudioRecording] (e.g. a stray second tap on the stop control) and
247	  /// — Review finding — ignored while a previous call is still awaiting
248	  /// `_micRecorder.stop()` ([_stopping]): without this, a fast double-tap
249	  /// on the stop control could fire a second `_micRecorder.stop()` call
250	  /// that returns `null` (nothing left to stop) and clobber the first
251	  /// call's genuine result with a bogus `AudioError`.
252	  Future<void> stopRecording() async {
253	    if (state is! AudioRecording || _stopping) {
254	      return;
255	    }
256	    _stopping = true;
257	    final generation = _generation;
258	    _elapsedTimer?.cancel();
259	    MicRecording? recording;
260	    try {
261	      recording = await _micRecorder.stop();
262	    } catch (_) {
263	      // Review finding: a thrown `PlatformException` must never escape
264	      // uncaught — surfaces through the normal error/retry path instead.
265	      _stopping = false;
266	      if (isClosed || generation != _generation) {
267	        return;
268	      }
269	      emit(
270	        const AudioError(
271	          path: null,
272	          durationSeconds: null,
273	          message: 'Não foi possível gravar o áudio.',
274	        ),
275	      );
276	      return;
277	    }
278	    _stopping = false;
279	    // Review finding: without the `_generation` check, a `cancel()` that
280	    // ran while `_micRecorder.stop()` was in flight (tab switch right
281	    // after tapping stop) already reset the cubit to `AudioIdle` — this
282	    // continuation must not resurrect the flow with a stale
283	    // `AudioProcessing`/`AudioError` emission on top of that reset.
284	    if (isClosed || generation != _generation) {
285	      return;
286	    }
287	    if (recording == null) {
288	      // Stopped with nothing actually captured — the I/O matrix has no
289	      // dedicated row for this (it should be unreachable in practice: the
290	      // recorder was just started above), but `AudioError` with no file
291	      // still gives the user a path back in via retry's permission-
292	      // re-request branch rather than leaving the cubit stuck mid-flow.
293	      emit(
294	        const AudioError(
295	          path: null,
296	          durationSeconds: null,
297	          message: 'Não foi possível gravar o áudio.',
298	        ),
299	      );
300	      return;
301	    }
302	    emit(
303	      AudioProcessing(
304	        path: recording.path,
305	        durationSeconds: recording.durationSeconds,
306	      ),
307	    );
308	    await _transcribe(recording.path, recording.durationSeconds);
309	  }
310	
311	  Future<void> _transcribe(String path, int durationSeconds) async {
312	    final text = await _audioTranscriber.transcribe(path);
313	    if (isClosed) {
314	      return;
315	    }
316	    // Guards a tab switch away mid-processing (`cancel()`, below) that
317	    // already reset the state to `AudioIdle` by the time this resolves —
318	    // without this, the eventual transcription result would still land
319	    // and resurrect a flow the user already left.
320	    if (state is! AudioProcessing ||
321	        (state as AudioProcessing).path != path) {
322	      return;
323	    }
324	    if (text == null) {
325	      emit(
326	        AudioError(
327	          path: path,
328	          durationSeconds: durationSeconds,
329	          message: 'Não foi possível transcrever o áudio.',
330	        ),
331	      );
332	      return;
333	    }
334	    emit(
335	      AudioTranscribed(
336	        path: path,
337	        durationSeconds: durationSeconds,
338	        text: text,
339	        saving: false,
340	      ),
341	    );
342	  }
343	
344	  /// "Tentar novamente" — re-requests permission when no file was ever
345	  /// recorded, or re-transcribes the same preserved file otherwise (I/O
346	  /// matrix: never re-records, never auto-retries on its own). A no-op
347	  /// outside [AudioError], or for a save failure (non-null [AudioError.
348	  /// text]) — that case's own retry is just tapping Salvar again, handled
349	  /// by [save] directly, not this method.
350	  Future<void> retry() async {
351	    final current = state;
352	    if (current is! AudioError || current.text != null) {
353	      return;
354	    }
355	    final path = current.path;
356	    final durationSeconds = current.durationSeconds;
357	    if (path == null || durationSeconds == null) {
358	      await startRecording();
359	      return;
360	    }
361	    emit(AudioProcessing(path: path, durationSeconds: durationSeconds));
362	    await _transcribe(path, durationSeconds);
363	  }
364	
365	  /// Mirrors the Texto field's own `updateText` — keeps the transcribed
366	  /// text editable before Salvar (Acceptance Criteria). Ignored while a
367	  /// save is already in flight, same rationale as `TextEntryCubit.
368	  /// updateText`.
369	  void updateText(String text) {
370	    final current = state;
371	    if (current is AudioTranscribed && !current.saving) {
372	      emit(current.copyWith(text: text));
373	    } else if (current is AudioError && current.text != null) {
374	      // Review finding: a save failure (`AudioError` with non-null
375	      // `text`) renders the same editable field as `AudioTranscribed`
376	      // (`_AudioErrorView`'s non-retry branch) — without this branch,
377	      // typing there updated the `TextField`'s own controller visually
378	      // but never the cubit's record of the text, so a retried `save()`
379	      // would silently resend the stale pre-failure text.
380	      emit(
381	        AudioError(
382	          path: current.path,
383	          durationSeconds: current.durationSeconds,
384	          message: current.message,
385	          text: text,
386	        ),
387	      );
388	    }
389	  }
390	
391	  /// Called when the Áudio tab loses focus mid-recording/mid-processing
392	  /// (`InsertionModal`'s tab-switch listener) — the I/O matrix's "Leave
393	  /// tab mid-recording" row: stops/releases the recorder, no `create()`
394	  /// ever fires. A no-op for every other state when [discardPreserved] is
395	  /// `false` (the default) — in particular [AudioTranscribed]/[AudioError],
396	  /// where the Never clause's trivial scope (resource safety only, not
397	  /// full Story 3.4 cancel-safety) means a tab switch must preserve the
398	  /// result rather than discard it.
399	  ///
400	  /// [discardPreserved] — Review finding: `InsertionModal.show()`'s
401	  /// `finally` also calls this (before `close()`) when the *whole modal*
402	  /// is dismissed (✕/swipe-down/barrier tap), not just the tab. In that
403	  /// case there's no "switch back to the tab later" to preserve for —
404	  /// the cubit is about to be closed — so a preserved [AudioTranscribed]
405	  /// or file-carrying [AudioError]'s temp file would otherwise never be
406	  /// cleaned up and leak on disk forever. Pass `true` only from that
407	  /// call site.
408	  Future<void> cancel({bool discardPreserved = false}) async {
409	    // Bumped unconditionally — including when the state below doesn't
410	    // match either branch — so an in-flight `startRecording()`/
411	    // `stopRecording()` continuation still sees the mismatch and aborts
412	    // itself (Review finding: previously only invalidated a flow already
413	    // visible in `state`, missing the window while those methods were
414	    // still awaiting).
415	    _generation++;
416	    final current = state;
417	    if (current is AudioRecording) {
418	      _elapsedTimer?.cancel();
419	      await _safeCancelRecorder();
420	      if (isClosed) {
421	        return;
422	      }
423	      emit(const AudioIdle());
424	    } else if (current is AudioProcessing) {
425	      // The recorder itself is already stopped by the time this state is
426	      // reached (`stopRecording` stops it before emitting `AudioProcessing`)
427	      // — only resetting the cubit's own state is left, so the pending
428	      // `_transcribe` continuation's own `state is! AudioProcessing` guard
429	      // (above) drops its result instead of resurrecting this flow. Review
430	      // finding: the already-recorded file is abandoned for good at this
431	      // point (nothing will ever retry it), so it must be deleted here —
432	      // the other orphan-file case `_micRecorder.cancel()` above already
433	      // handles on its own.
434	      unawaited(_deleteRecordingFile(current.path));
435	      emit(const AudioIdle());
436	    } else if (discardPreserved) {
437	      final path = switch (current) {
438	        AudioTranscribed(path: final p) => p,
439	        AudioError(path: final p) => p,
440	        _ => null,
441	      };
442	      if (path != null) {
443	        unawaited(_deleteRecordingFile(path));
444	      }
445	    }
446	  }
447	
448	  /// Best-effort `_micRecorder.cancel()` — a thrown `PlatformException`
449	  /// here (Review finding) must never escape uncaught, since both call
450	  /// sites (above, and [startRecording]'s own abandon-on-generation-
451	  /// mismatch branch) call this fire-and-forget.
452	  Future<void> _safeCancelRecorder() async {
453	    try {
454	      await _micRecorder.cancel();
455	    } catch (_) {
456	      // Best-effort — nothing in the UI depends on this succeeding.
457	    }
458	  }
459	
460	  /// I/O matrix's "Happy path"/"Save fails" rows: fires `POST /entries`
461	  /// with `source: audio` and `mediaDurationSeconds` for the current
462	  /// transcribed text. Mirrors `TextEntryCubit.save()`'s `isClosed`/
463	  /// no-double-submit guards exactly (Boundaries).
464	  ///
465	  /// Review finding: also callable from an [AudioError] save failure
466	  /// (non-null [AudioError.text]) — `_AudioErrorView`'s non-retry branch
467	  /// re-renders the editable field and calls this same method for its
468	  /// "Salvar" button, but the original guard only matched
469	  /// [AudioTranscribed], making a retry after any save failure a
470	  /// permanent no-op.
471	  Future<void> save() async {
472	    final current = state;
473	    final String path;
474	    final int durationSeconds;
475	    final String text;
476	    if (current is AudioTranscribed && !current.saving) {
477	      path = current.path;
478	      durationSeconds = current.durationSeconds;
479	      text = current.text.trim();
480	    } else if (current is AudioError &&
481	        current.text != null &&
482	        current.path != null &&
483	        current.durationSeconds != null) {
484	      path = current.path!;
485	      durationSeconds = current.durationSeconds!;
486	      text = current.text!.trim();
487	    } else {
488	      return;
489	    }
490	    if (text.isEmpty) {
491	      return;
492	    }
493	    emit(
494	      AudioTranscribed(
495	        path: path,
496	        durationSeconds: durationSeconds,
497	        text: text,
498	        saving: true,
499	      ),
500	    );
501	    final result = await _repository.create(
502	      content: text,
503	      source: EntrySource.audio,
504	      mediaDurationSeconds: durationSeconds,
505	    );
506	    // Mirrors `TextEntryCubit.save()`'s own `isClosed` guard — this
507	    // cubit's `close()` can race the awaited call above (e.g. the modal's
508	    // barrier is dismissed mid-save).
509	    if (isClosed) {
510	      return;
511	    }
512	    result.match(
513	      (failure) => emit(
514	        AudioError(
515	          path: path,
516	          durationSeconds: durationSeconds,
517	          message: failure.message,
518	          text: text,
519	        ),
520	      ),
521	      (_) {
522	        // Review finding: the recorded temp file was never deleted after
523	        // a successful save — fire-and-forget, a deletion failure must
524	        // never block the modal from closing.
525	        unawaited(_deleteRecordingFile(path));
526	        emit(const AudioSaved());
527	      },
528	    );
529	  }
530	
531	  /// Best-effort cleanup for a temp recording file this cubit is done
532	  /// with (saved successfully, or abandoned for good by [cancel] mid-
533	  /// processing) — deletion failures are swallowed since nothing in the
534	  /// UI depends on this succeeding (Review finding: previously never
535	  /// called at all, leaking a `.wav` file per recording indefinitely).
536	  Future<void> _deleteRecordingFile(String path) async {
537	    try {
538	      await File(path).delete();
539	    } catch (_) {
540	      // Best-effort — a missing/already-deleted file, or a transient
541	      // disk error, is never worth surfacing to the user.
542	    }
543	  }
544	
545	  @override
546	  Future<void> close() {
547	    _elapsedTimer?.cancel();
548	    return super.close();
549	  }
550	}
