14	/// AD-2/AD-5 — the one network façade every repository's data source calls
15	/// through. Builds the real URL via `UrlBuilder`, sends the request through
16	/// `dio` (header + retry interceptors already attached in DI), and maps
17	/// every outcome — success or failure — to `Either<Failure, T>`; no
18	/// dio/native exception ever escapes unmapped (RNF09).
19	///
20	/// Story 1.5: also the one detection point for a mid-session `AUTH_EXPIRED`
21	/// — signals [SessionExpiryNotifier] when one is seen outside
22	/// `HeaderInterceptor.anonKeyOnlyFunctions`, so the boot-time `auth-refresh`
23	/// call (Story 1.4's `restoreSession()`) never triggers it.
24	///
25	/// Tests mock this interface directly (per the architecture spine's testing
26	/// convention), not a fake transport layer underneath it.
27	class ApiClient {
28	  ApiClient({
29	    required Dio dio,
30	    required UrlBuilder urlBuilder,
31	    required SessionExpiryNotifier sessionExpiryNotifier,
32	  })  : _dio = dio,
33	        _urlBuilder = urlBuilder,
34	        _sessionExpiryNotifier = sessionExpiryNotifier;
35	
36	  final Dio _dio;
37	  final UrlBuilder _urlBuilder;
38	  final SessionExpiryNotifier _sessionExpiryNotifier;
39	
40	  Future<Either<Failure, Map<String, dynamic>>> get(
41	    String function, {
42	    List<String> pathParams = const [],
43	    Map<String, dynamic>? queryParameters,
44	  }) =>
45	      _send(
46	        () => _dio.get<Map<String, dynamic>>(
47	          _urlBuilder.build(function, pathParams),
48	          queryParameters: queryParameters,
49	        ),
50	      );
51	
52	  Future<Either<Failure, Map<String, dynamic>>> post(
53	    String function, {
54	    List<String> pathParams = const [],
55	    Object? data,
56	  }) =>
57	      _send(
58	        () => _dio.post<Map<String, dynamic>>(
59	          _urlBuilder.build(function, pathParams),
60	          data: data,
61	        ),
62	      );
63	
64	  Future<Either<Failure, Map<String, dynamic>>> patch(
65	    String function, {
66	    List<String> pathParams = const [],
67	    Object? data,
68	  }) =>
69	      _send(
70	        () => _dio.patch<Map<String, dynamic>>(
71	          _urlBuilder.build(function, pathParams),
72	          data: data,
73	        ),
74	      );
75	
76	  Future<Either<Failure, Map<String, dynamic>>> delete(
77	    String function, {
78	    List<String> pathParams = const [],
79	    Object? data,
80	  }) =>
81	      _send(
82	        () => _dio.delete<Map<String, dynamic>>(
83	          _urlBuilder.build(function, pathParams),
84	          data: data,
85	        ),
86	      );
