88	  Future<Either<Failure, Map<String, dynamic>>> _send(
89	    Future<Response<Map<String, dynamic>>> Function() request,
90	  ) async {
91	    try {
92	      final response = await request();
93	      final data = response.data;
94	      if (data == null) {
95	        return left(
96	          const Failure.malformedResponse(message: 'Empty response body'),
97	        );
98	      }
99	      return right(data);
100	    } on DioException catch (e) {
101	      return left(_mapDioException(e));
102	    } catch (e) {
103	      return left(Failure.malformedResponse(message: e.toString()));
104	    }
105	  }
106	
107	  Failure _mapDioException(DioException e) {
108	    final code = dioErrorCodeOf(e);
109	    if (code == null) {
110	      // Covers a cancelled request and an HTTP response that doesn't carry
111	      // the expected `{code, message, retryable}` body — neither is one of
112	      // the 13 backend codes, so neither is retryable (dioErrorCodeOf).
113	      return Failure.malformedResponse(
114	        message: e.message ?? 'Malformed response',
115	      );
116	    }
117	    final data = e.response?.data;
118	    final message = data is Map ? data['message'] : null;
119	    final failure = Failure.fromCode(
120	      code,
121	      (message is String ? message : null) ?? e.message ?? 'Unknown error',
122	    );
123	    if (failure is AuthExpired && !_isAnonKeyOnlyCall(e)) {
124	      _sessionExpiryNotifier.notifyExpired();
125	    }
126	    return failure;
127	  }
128	
129	  /// Whether [e]'s request targeted one of the three `security: []`
130	  /// operations (signup, login, refresh) — the only calls `AUTH_EXPIRED`
131	  /// must never be treated as a mid-session expiry for, since those are the
132	  /// anon-keyed calls Story 1.4's `restoreSession()` itself makes.
133	  ///
134	  /// Mirrors `HeaderInterceptor.onRequest`'s own fail-open behavior: a
135	  /// malformed `requestOptions.path` (shouldn't happen — `UrlBuilder`
136	  /// always produces a valid URL) is treated as "not anon-key-only" rather
137	  /// than letting a `FormatException` escape this mapping step unmapped
138	  /// (RNF09).
139	  bool _isAnonKeyOnlyCall(DioException e) {
140	    String function;
141	    try {
142	      function = HeaderInterceptor.functionNameOf(e.requestOptions.path);
143	    } catch (_) {
144	      function = '';
145	    }
146	    return HeaderInterceptor.anonKeyOnlyFunctions.contains(function);
147	  }
148	}
